namespace Emprestimo;

public static class Calculadora
{
    public static decimal[] Parcelas(decimal valor, decimal taxaMensalPct, int meses)
    {
        if (valor <= 0)
            throw new ArgumentOutOfRangeException(
                nameof(valor),
                "O valor precisa ser maior que zero.");
        if (meses < 1)
            throw new ArgumentOutOfRangeException(
                nameof(meses),
                "Precisa de pelo menos 1 parcela.");
        if (taxaMensalPct < 0)
            throw new ArgumentOutOfRangeException(
                nameof(taxaMensalPct),
                "A taxa não pode ser negativa.");

        decimal taxa = taxaMensalPct / 100m;
        decimal parcela;
        if (taxa == 0)
        {
            parcela = valor / meses;
        }
        else
        {
            decimal fator = 1m;
            for (int i = 0; i < meses; i++)
            {
                fator *= 1 + taxa;
            }
            parcela = valor * taxa * fator / (fator - 1);
        }

        decimal redonda = Math.Round(parcela, 2, MidpointRounding.AwayFromZero);
        decimal[] parcelas = Enumerable.Repeat(redonda, meses).ToArray();
        if (taxa == 0)
        {
            parcelas[^1] = valor - redonda * (meses - 1);
        }
        return parcelas;
    }
}

Crie Emprestimo.Tests/CalculadoraTests.cs (o template do xUnit já importa o namespace Xunit para o projeto inteiro):
using Emprestimo;

namespace Emprestimo.Tests;

public class CalculadoraTests
{
    [Fact]
    public void Basico_1000_a_2_por_cento_em_12x()
    {
        decimal[] parcelas = Calculadora.Parcelas(1000m, 2m, 12);

        Assert.Equal(12, parcelas.Length);
        Assert.All(parcelas, p => Assert.Equal(94.56m, p));
    }

    [Fact]
    public void Taxa_zero_divide_sem_juros()
    {
        decimal[] parcelas = Calculadora.Parcelas(1000m, 0m, 4);

        Assert.All(parcelas, p => Assert.Equal(250m, p));
    }

    [Fact]
    public void Centavos_fecham_a_conta()
    {
        decimal[] parcelas = Calculadora.Parcelas(1000m, 0m, 3);

        Assert.Equal(new[] { 333.33m, 333.33m, 333.34m }, parcelas);
        Assert.Equal(1000m, parcelas.Sum());
    }

    [Fact]
    public void Entrada_invalida_lanca_excecao()
    {
        Assert.Throws<ArgumentOutOfRangeException>(() => Calculadora.Parcelas(0m, 2m, 12));
        Assert.Throws<ArgumentOutOfRangeException>(() => Calculadora.Parcelas(1000m, 2m, 0));
        Assert.Throws<ArgumentOutOfRangeException>(() => Calculadora.Parcelas(1000m, -1m, 12));
    }
}
